<?php
namespace ProjectPress\Admin\Manager\Projects;
use ProjectPress\Includes\Functions\Helpers\RequestHelper;use ProjectPress\Includes\Project\Core\Project;use ProjectPress\Includes\Project\Core\ProjectPermissions;use ProjectPress\Includes\Project\Governance\GovernanceRepository;use ProjectPress\Includes\Project\Governance\GovernanceService;use ProjectPress\Includes\Project\ProjectManager as DomainProjectManager;use WP_Error;
if(!defined('ABSPATH')){exit;}
final class Governance{
 private DomainProjectManager $projects;private ProjectPermissions $permissions;private const TYPES=array('risk'=>'Risks','issue'=>'Issues','dependency'=>'Dependencies','decision'=>'Decisions');
 public function __construct(?DomainProjectManager$projects=null,?ProjectPermissions$permissions=null){$this->projects=$projects??DomainProjectManager::get_instance();$this->permissions=$permissions??new ProjectPermissions();}
 public function render(Project$project):void{$can=$this->permissions->can_edit($project);?><div class="row g-4"><?php foreach(self::TYPES as$type=>$label):$repo=new GovernanceRepository($type);$items=$repo->for_project($project->get_id());?><div class="col-xl-6"><div class="card card-body h-100"><h2 class="h4"><?php echo esc_html(__($label,'projectpress'));?></h2><?php if(empty($items)):?><p class="text-secondary"><?php esc_html_e('No records have been added yet.','projectpress');?></p><?php endif;foreach($items as$item):?><div class="border rounded p-2 mb-2"><strong><?php echo esc_html((string)$item->get('title',''));?></strong><div class="small text-secondary"><?php echo esc_html(ucwords(str_replace('_',' ',(string)$item->get('status','open'))));?></div><?php if($can):?><form class="mt-2" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="projectpress_workspace_governance_delete"/><input type="hidden" name="project_id" value="<?php echo esc_attr((string)$project->get_id());?>"/><input type="hidden" name="type" value="<?php echo esc_attr($type);?>"/><input type="hidden" name="record_id" value="<?php echo esc_attr((string)$item->get_id());?>"/><?php wp_nonce_field('projectpress_workspace_governance_delete');?><button class="btn btn-sm btn-outline-danger" type="submit"><?php esc_html_e('Delete','projectpress');?></button></form><?php endif;?></div><?php endforeach;?><?php if($can):?><form class="mt-3" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="projectpress_workspace_governance_save"/><input type="hidden" name="project_id" value="<?php echo esc_attr((string)$project->get_id());?>"/><input type="hidden" name="type" value="<?php echo esc_attr($type);?>"/><?php wp_nonce_field('projectpress_workspace_governance_save');?><label class="form-label"><?php esc_html_e('Title','projectpress');?></label><input class="form-control" name="title" required/><label class="form-label mt-2"><?php esc_html_e('Description','projectpress');?></label><textarea class="form-control" name="description"></textarea><label class="form-label mt-2"><?php esc_html_e('Status','projectpress');?></label><input class="form-control" name="status" value="open"/><label class="form-label mt-2"><?php esc_html_e('Related record type','projectpress');?></label><input class="form-control" name="target_type"/><label class="form-label mt-2"><?php esc_html_e('Related record ID','projectpress');?></label><input class="form-control" type="number" min="0" name="target_id"/><?php if('risk'===$type):?><label class="form-label mt-2"><?php esc_html_e('Probability','projectpress');?></label><input class="form-control" name="probability"/><label class="form-label mt-2"><?php esc_html_e('Impact','projectpress');?></label><input class="form-control" name="impact"/><?php endif;?><button class="btn btn-primary mt-3" type="submit"><?php echo esc_html(sprintf(__('Add %s','projectpress'),rtrim($label,'s')));?></button></form><?php endif;?></div></div><?php endforeach;?></div><?php }
 public function handle_save():void{check_admin_referer('projectpress_workspace_governance_save');$project_id=RequestHelper::integer($_POST,'project_id',0);$type=RequestHelper::key($_POST,'type','');if(!isset(self::TYPES[$type])){$this->redirect($project_id,new WP_Error('projectpress_governance_type_invalid',__('Invalid governance type.','projectpress')));}$repo=new GovernanceRepository($type);$service=new GovernanceService($type,$repo,$this->projects->repository(),$this->permissions);$result=$service->create($project_id,array('title'=>RequestHelper::text($_POST,'title',''),'description'=>RequestHelper::text($_POST,'description',''),'status'=>RequestHelper::key($_POST,'status','open'),'probability'=>RequestHelper::key($_POST,'probability',''),'impact'=>RequestHelper::key($_POST,'impact',''),'target_type'=>RequestHelper::key($_POST,'target_type',''),'target_id'=>RequestHelper::integer($_POST,'target_id',0)));$this->redirect($project_id,$result);}
 public function handle_delete():void{check_admin_referer('projectpress_workspace_governance_delete');$project_id=RequestHelper::integer($_POST,'project_id',0);$type=RequestHelper::key($_POST,'type','');if(!isset(self::TYPES[$type])){$this->redirect($project_id,new WP_Error('projectpress_governance_type_invalid',__('Invalid governance type.','projectpress')));}$repo=new GovernanceRepository($type);$record=$repo->find(RequestHelper::integer($_POST,'record_id',0));if(!$record||$record->get_project_id()!==$project_id){$this->redirect($project_id,new WP_Error('projectpress_governance_not_found',__('Governance record not found.','projectpress')));}$service=new GovernanceService($type,$repo,$this->projects->repository(),$this->permissions);$this->redirect($project_id,$service->delete($record));}
 private function redirect(int$project_id,$result):void{$url=add_query_arg(array('page'=>'projectpress','group'=>'projects','project_id'=>absint($project_id),'tab'=>'governance'),admin_url('admin.php'));$url=is_wp_error($result)?add_query_arg('project_error',rawurlencode($result->get_error_message()),$url):add_query_arg('project_saved','1',$url);wp_safe_redirect($url);exit;}
}
